    (v_aula_id, 1, $p$Agostinho consolou-se ao lembrar que a fé está alicerçada em Cristo, e não num sistema político: quando você olha para as mudanças culturais que o assustam, o quanto da sua paz tem dependido de um cenário político favorável em vez de depender de Cristo?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$A autora percebeu que as tensões que sentia eram respostas compreensíveis à mudança cultural, mas não precisavam virar pânico: que ansiedades você tem carregado diante do mundo de hoje, e como a longa tradição de fé que sobreviveu a tantas crises poderia tranquilizar o seu coração?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Diante da queda de Roma, muitos buscaram culpados rápidos: quando algo desmorona ao seu redor, você corre para acusar, ou aprende com a história a interpretar os fatos com mais maturidade e fé?$p$, 'reflexao', null);
  end if;

