    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values

    (v_aula_id, 1, $p$A autora descobriu que tinha vivido uma fé excessivamente individualista, sem perceber que pertencer a Cristo é também pertencer à família de Deus: o quanto da sua fé você vive sozinho, e o que mudaria se você assumisse de fato que não foi chamado a caminhar isolado?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Ela passou a entender que buscar o reino é um chamado coletivo, e que "não tudo depende de mim": que pesos você tem carregado como se a missão dependesse só de você, e como seria entregá-los ao corpo de Cristo?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Agostinho não conseguia imaginar cristãos que não se vissem automaticamente como irmãos: quando você olha para a igreja, você a enxerga como uma família a quem pertence, ou apenas como um lugar onde recebe algo para si?$p$, 'reflexao', null);
  end if;

