    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values

    (v_aula_id, 1, $p$Na Mongólia, Tom e Nancy se viram "cegos, surdos e mudos", inexperientes e marginalizados, e essas vulnerabilidades os convidaram a abraçar novas virtudes: que vulnerabilidade você costuma esconder, e como ela poderia, em vez disso, virar porta para a humildade que Deus quer formar em você?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Newbigin fala de testemunhar do evangelho não de uma posição de força, mas de fragilidade: o quanto da sua maneira de viver a fé ainda se apoia em poder, influência ou recursos, em vez de na dependência de Deus?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Eles descobriram que não podiam resolver os problemas com dinheiro nem com técnicas: que problemas você tem tentado resolver com seus próprios recursos, quando talvez Deus o esteja chamando a abraçar a humildade e confiar nele?$p$, 'reflexao', null);
  end if;

