    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values

    (v_aula_id, 1, $p$Tom dizia aos estudantes que o que importa não é o erro que você comete, mas o que você faz depois dele: quando você falha diante dos outros, sua reação automática é se encolher de vergonha, fingir que nada houve, ou intervir com humildade e reparação?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O autor descreve quem foi criado para sempre acertar e por isso fugiu do fracasso a vida toda: o quanto o seu medo de errar tem impedido você de se arriscar a amar, testemunhar e servir num mundo onde tropeçar é inevitável?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Ele convida a estender graça a si mesmo e a tratar a falha como chance de aprofundar relacionamentos: há algum erro do passado que você ainda usa para se condenar, em vez de deixá-lo virar oportunidade de crescer e se aproximar de alguém?$p$, 'reflexao', null);
  end if;

