  if v_aula_id is null then
    insert into public.aulas (curso_id, titulo, ordem, conteudo)
    values (v_curso_id, $t$É no relacionamento que nos descobrimos$t$, 24,
$conteudo$Pesquisadores que estudam o desenvolvimento humano há tempos compreenderam que nenhum de nós é um indivíduos isolado. Os seres humanos — desde antes do nascimento e por toda a vida — são formados para o relacionamento e precisam dele. O conjunto de capacidades e de habilidades que associamos a ter um “eu” — as capacidades de nos distinguirmos do outro, de sentirmos e de dar nome à emoção e à fé, de refletir sobre nossa experiência, de agir com propósito —, tudo isso emerge nos laços relacionais entre mãe e filho, pai e filho, cuidador e criança, e crianças umas com as outras. Nunca como indivíduos, mas no relacionamento é que encontramos a nós mesmos. Outros nos refletem para nós mesmos e nos permitem descobrir quem somos. Os relacionamentos são fundamentais para a nossa felicidade, para nosso sentido de significado e de propósito, para nossa identidade pessoal.

Tendo me formado no evangelho da realização e da competência, me esforço para buscar relacionamentos que não estejam de algum modo associados à produtividade. Contudo, aprendi que não é pelo conhecimento ou pela técnica que me torno mais humano, e sim pelo compartilhamento da vida com outros. Estou aprendendo a reservar tempo e espaço para os relacionamentos que importam, a começar pela minha esposa. Mas também venho descobrindo, como psiquiatra, que a qualidade do meu relacionamento com meus pacientes é, no mínimo, tão importante para sua cura e recuperação quanto as técnicas que uso. É fácil imaginar que os médicos que atendem fora do hospital sejam veículos de receitas e procedimentos que são, por si mesmos, a fonte real da cura: os médicos, segundo essa forma de pensamento, são basicamente máquinas automáticas de receitas sobrevalorizadas. Contudo, se cultivo um relacionamento com os pacientes em que eles confiam em mim (e vice-versa), em que somos capazes de conversar honestamente e em que conseguimos discernir juntos o que é mais importante no seu tratamento, isto será fator de cura para eles e de energização para mim. O paciente se sentirá menos só, mais disposto a se abrir e mais vulnerável, e menos inclinado a pensar fixamente em suicídio como forma de escape. Em alguns casos, o paciente poderá reduzir o número e a intensidade das doses de remédio. Além de fazer simplesmente com que os pacientes se sintam à vontade para discutir as opções de tratamento, há evidências de que uma forte parceria terapêutica entre o clínico que faz a prescrição e o paciente ajuda de fato o funcionamento mais eficaz dos remédios psiquiátricos.$conteudo$)
    returning id into v_aula_id;
    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values

    (v_aula_id, 1, $p$O texto afirma que nunca nos descobrimos como indivíduos isolados, mas sempre no relacionamento, pois é o outro que nos reflete quem somos: o quanto você tem tentado se "resolver" sozinho, quando a sua cura e o seu crescimento dependem de partilhar a vida com outros?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Formado pelo "evangelho da realização e da competência", o autor luta para buscar relações não ligadas à produtividade: as suas amizades são vínculos genuínos, ou você só se aproxima de quem lhe é útil de alguma forma?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Ele descobriu que a qualidade do relacionamento cura tanto quanto a técnica: em que parte da sua vida você tem agido como uma "máquina de soluções", e onde, na verdade, as pessoas precisam mais da sua presença do que das suas respostas?$p$, 'reflexao', null);
  end if;

  select id into v_aula_id from public.aulas where curso_id = v_curso_id and ordem = 25;
